import android.view.*;import android.widget.*;import com.nice.room.ui.*;import com.nice.room.ui.roomlive.fragment.ask.answer.*;import com.hljzjx.classroom.mod.*;
public class NoResultBaselineTest{
static TextView visible(View v,String text){if(v.visibility!=View.VISIBLE)return null;if(v instanceof TextView && text.equals(((TextView)v).text))return (TextView)v;if(v instanceof ViewGroup)for(View child:((ViewGroup)v).children){TextView b=visible(child,text);if(b!=null)return b;}return null;}
public static void main(String[] args){RoomLiveActivity a=new RoomLiveActivity();FrameLayout host=new FrameLayout(a),root=new FrameLayout(a);host.id=200;host.attach();host.addView(root,new FrameLayout.LayoutParams(-1,-1,0));QuestionAskHandwriteFragment f=new QuestionAskHandwriteFragment();f.root=root;QuestionPptReturn.install(root);QuestionActions.install(f,root);View.drain();f.finished=true;root.tree.global();View.drain();if(visible(host,"继续作答")==null)throw new AssertionError("timer end without a result must expose Continue");System.out.println("PASS missing-result timer regression");}}
